do {
  const data = await graphql<{ viewer: { login: string }; org?: { projectV2: ProjectData }; user?: { projectV2: ProjectData } }>(
    token,
    PROJECT_ITEMS_QUERY,
    { login: owner, number: projectNumber, isOrg, cursor }
  );

  if (!viewerLogin) viewerLogin = data.viewer?.login ?? '';

  const project = isOrg ? data.org?.projectV2 : data.user?.projectV2;
  if (!project) {
    throw new Error(`Project #${projectNumber} not found for ${owner}`);
  }

  projectTitle = project.title;
  allNodes.push(...project.items.nodes);

  if (project.items.pageInfo.hasNextPage) {
    cursor = project.items.pageInfo.endCursor;

