            void vscode.window.showTextDocument(uri);
          }
        }
      },
      null,
      this._disposables
    );
  }

  private async _loadData() {
    this._panel.webview.postMessage({ type: 'loading' });
    try {
      const data = await buildCodemapData();
      this._panel.webview.postMessage({ type: 'data', payload: data });
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      this._panel.webview.postMessage({ type: 'error', message });
    }
  }

  private _buildHtml(webview: vscode.Webview): string {
    const scriptUri = webview.asWebviewUri(
      vscode.Uri.joinPath(this._extensionUri, 'out', 'codemaps.js')
    );
    const nonce = getNonce();

    return /* html */ `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <meta http-equiv="Content-Security-Policy"
