    * { box-sizing: border-box; margin: 0; padding: 0; }
    body { background: #0d0d0d; color: #e0e0e0; font-family: var(--vscode-font-family, system-ui); overflow: hidden; }
    #root { width: 100vw; height: 100vh; }
