import React, { useCallback, useEffect, useRef, useState } from 'react';

// ─── Types ────────────────────────────────────────────────────────────────────

interface CodemapNode { id: string; label: string; ext: string; dir: string }
interface CodemapEdge { source: string; target: string }
interface CodemapData  { nodes: CodemapNode[]; edges: CodemapEdge[]; root: string }

interface SimNode extends CodemapNode {
  x: number; y: number; vx: number; vy: number; pinned?: boolean;
}

// ─── VS Code API ──────────────────────────────────────────────────────────────

declare function acquireVsCodeApi(): {
  postMessage(msg: unknown): void;
};
const vscode = acquireVsCodeApi();

// ─── Colors ───────────────────────────────────────────────────────────────────

const EXT_COLOR: Record<string, string> = {
  '.ts':  '#4FC3F7',
  '.tsx': '#CE93D8',
  '.js':  '#FFD54F',
  '.jsx': '#FFAB40',
  '.mjs': '#80CBC4',
};
function nodeColor(ext: string) { return EXT_COLOR[ext] ?? '#90A4AE'; }

// ─── Force simulation (Fruchterman–Reingold) ──────────────────────────────────

function runSimulation(nodes: SimNode[], edges: CodemapEdge[], W: number, H: number, ticks = 250) {
  if (nodes.length === 0) return;

  const area = W * H;
  const k = Math.sqrt(area / nodes.length);
  const cx = W / 2, cy = H / 2;

  // Build adjacency for O(1) lookup
  const adj = new Set(edges.map(e => `${e.source}|${e.target}`));
  const connected = (a: string, b: string) => adj.has(`${a}|${b}`) || adj.has(`${b}|${a}`);

  for (let t = 0; t < ticks; t++) {
    const temp = k * (1 - t / ticks);   // cooling

    // repulsion between all pairs
    for (let i = 0; i < nodes.length; i++) {
      nodes[i].vx = 0; nodes[i].vy = 0;
      for (let j = 0; j < nodes.length; j++) {
        if (i === j) continue;
        let dx = nodes[i].x - nodes[j].x;
        let dy = nodes[i].y - nodes[j].y;
        const dist = Math.sqrt(dx * dx + dy * dy) || 0.01;
        const rep = (k * k) / dist;
        nodes[i].vx += (dx / dist) * rep;
        nodes[i].vy += (dy / dist) * rep;
      }
    }

    // spring attraction along edges
    for (const e of edges) {
      const s = nodes.find(n => n.id === e.source);
      const t2 = nodes.find(n => n.id === e.target);
      if (!s || !t2) continue;
      const dx = t2.x - s.x, dy = t2.y - s.y;
      const dist = Math.sqrt(dx * dx + dy * dy) || 0.01;
      const attr = (dist * dist) / k;
      const fx = (dx / dist) * attr, fy = (dy / dist) * attr;
      s.vx += fx; s.vy += fy;
      t2.vx -= fx; t2.vy -= fy;
    }

    // centering
    for (const n of nodes) {
      n.vx += (cx - n.x) * 0.02;
      n.vy += (cy - n.y) * 0.02;
    }

    // apply velocity with cooling + clamp
    for (const n of nodes) {
      if (n.pinned) continue;
      const speed = Math.sqrt(n.vx * n.vx + n.vy * n.vy) || 1;
      const scale = Math.min(speed, temp) / speed;
      n.x = Math.max(40, Math.min(W - 40, n.x + n.vx * scale));
      n.y = Math.max(40, Math.min(H - 40, n.y + n.vy * scale));
    }

    // cluster nodes by directory (mild attraction)
    const dirCenters: Record<string, { x: number; y: number; count: number }> = {};
    for (const n of nodes) {
      if (!dirCenters[n.dir]) dirCenters[n.dir] = { x: 0, y: 0, count: 0 };
      dirCenters[n.dir].x += n.x;
      dirCenters[n.dir].y += n.y;
      dirCenters[n.dir].count++;
    }
    for (const dc of Object.values(dirCenters)) { dc.x /= dc.count; dc.y /= dc.count; }
    for (const n of nodes) {
      const dc = dirCenters[n.dir];
      if (!dc) continue;
      n.x += (dc.x - n.x) * 0.01;
      n.y += (dc.y - n.y) * 0.01;
    }
  }
}

// ─── Component ────────────────────────────────────────────────────────────────

type State =
  | { status: 'idle' }
  | { status: 'loading' }
  | { status: 'error'; message: string }
  | { status: 'ready'; data: CodemapData; nodes: SimNode[] };

export function CodemapsView() {
  const svgRef = useRef<SVGSVGElement>(null);
  const [state, setState] = useState<State>({ status: 'idle' });
  const [dims, setDims] = useState({ w: window.innerWidth, h: window.innerHeight });

  // pan/zoom
  const [transform, setTransform] = useState({ x: 0, y: 0, scale: 1 });
  const panStart = useRef<{ px: number; py: number; tx: number; ty: number } | null>(null);
  const isPanning = useRef(false);

  // dragging a node
  const dragNode = useRef<{ id: string; offsetX: number; offsetY: number } | null>(null);

  // hover
  const [hovered, setHovered] = useState<string | null>(null);

  // ── resize ──
  useEffect(() => {
    const onResize = () => setDims({ w: window.innerWidth, h: window.innerHeight });
    window.addEventListener('resize', onResize);
    return () => window.removeEventListener('resize', onResize);
  }, []);

  // ── messages from extension ──
  useEffect(() => {
    const onMsg = (ev: MessageEvent) => {
      const msg = ev.data as
        | { type: 'loading' }
        | { type: 'error'; message: string }
        | { type: 'data'; payload: CodemapData };

      if (msg.type === 'loading') {
        setState({ status: 'loading' });
      } else if (msg.type === 'error') {
        setState({ status: 'error', message: msg.message });
      } else if (msg.type === 'data') {
        const { nodes: raw, edges, root } = msg.payload;
        const W = window.innerWidth, H = window.innerHeight;

        // place nodes on a circle initially
        const simNodes: SimNode[] = raw.map((n, i) => {
          const angle = (2 * Math.PI * i) / raw.length;
          const r = Math.min(W, H) * 0.38;
          return { ...n, x: W / 2 + r * Math.cos(angle), y: H / 2 + r * Math.sin(angle), vx: 0, vy: 0 };
        });

        runSimulation(simNodes, edges, W, H);
        setState({ status: 'ready', data: { nodes: raw, edges, root }, nodes: simNodes });
        setTransform({ x: 0, y: 0, scale: 1 });
      }
    };
    window.addEventListener('message', onMsg);
    vscode.postMessage({ type: 'ready' });
    return () => window.removeEventListener('message', onMsg);
  }, []);

  // ── helpers ──
  const screenToSvg = (px: number, py: number) => ({
    x: (px - transform.x) / transform.scale,
    y: (py - transform.y) / transform.scale,
  });

  const fitToScreen = useCallback(() => {
    if (state.status !== 'ready') return;
    const { nodes } = state;
    if (nodes.length === 0) return;
    const xs = nodes.map(n => n.x), ys = nodes.map(n => n.y);
    const minX = Math.min(...xs) - 60, maxX = Math.max(...xs) + 60;
    const minY = Math.min(...ys) - 60, maxY = Math.max(...ys) + 60;
    const scaleX = dims.w / (maxX - minX);
    const scaleY = dims.h / (maxY - minY);
    const scale = Math.min(scaleX, scaleY, 2);
    const tx = dims.w / 2 - ((minX + maxX) / 2) * scale;
    const ty = dims.h / 2 - ((minY + maxY) / 2) * scale;
    setTransform({ x: tx, y: ty, scale });
  }, [state, dims]);

  // ── zoom ──
  const onWheel = (e: React.WheelEvent) => {
    e.preventDefault();
    const factor = e.deltaY < 0 ? 1.12 : 1 / 1.12;
    setTransform(prev => {
      const newScale = Math.max(0.1, Math.min(8, prev.scale * factor));
      const dx = e.clientX - prev.x;
      const dy = e.clientY - prev.y;
      return {
        scale: newScale,
        x: e.clientX - dx * (newScale / prev.scale),
        y: e.clientY - dy * (newScale / prev.scale),
      };
    });
  };

  // ── pan (background drag) ──
  const onBgPointerDown = (e: React.PointerEvent) => {
    if (e.button !== 0) return;
    isPanning.current = true;
    panStart.current = { px: e.clientX, py: e.clientY, tx: transform.x, ty: transform.y };
    (e.target as Element).setPointerCapture(e.pointerId);
  };
  const onPointerMove = (e: React.PointerEvent) => {
    if (dragNode.current && state.status === 'ready') {
      const { x, y } = screenToSvg(e.clientX, e.clientY);
      setState(prev => {
        if (prev.status !== 'ready') return prev;
        return {
          ...prev,
          nodes: prev.nodes.map(n =>
            n.id === dragNode.current!.id
              ? { ...n, x: x - dragNode.current!.offsetX, y: y - dragNode.current!.offsetY, pinned: true }
              : n
          ),
        };
      });
    } else if (isPanning.current && panStart.current) {
      setTransform(prev => ({
        ...prev,
        x: panStart.current!.tx + e.clientX - panStart.current!.px,
        y: panStart.current!.ty + e.clientY - panStart.current!.py,
      }));
    }
  };
  const onPointerUp = () => {
    isPanning.current = false;
    panStart.current = null;
    dragNode.current = null;
  };

  // ── node drag ──
  const onNodePointerDown = (e: React.PointerEvent, n: SimNode) => {
    e.stopPropagation();
    const { x, y } = screenToSvg(e.clientX, e.clientY);
    dragNode.current = { id: n.id, offsetX: x - n.x, offsetY: y - n.y };
    (e.target as Element).setPointerCapture(e.pointerId);
  };
  const onNodeClick = (e: React.MouseEvent, n: SimNode) => {
    e.stopPropagation();
    vscode.postMessage({ type: 'openFile', path: n.id });
  };

  // ── render ──
  const toolbar = (
    <div style={{
      position: 'absolute', top: 12, left: 12, display: 'flex', gap: 6, zIndex: 10,
      background: 'rgba(20,20,20,0.85)', borderRadius: 8, padding: '6px 10px',
      backdropFilter: 'blur(8px)', border: '1px solid rgba(255,255,255,0.08)',
    }}>
      <button onClick={() => vscode.postMessage({ type: 'refresh' })} title="Refresh" style={btnStyle}>
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
          <polyline points="23 4 23 10 17 10"/><polyline points="1 20 1 14 7 14"/>
          <path d="M3.51 9a9 9 0 0 1 14.85-3.36L23 10M1 14l4.64 4.36A9 9 0 0 0 20.49 15"/>
        </svg>
      </button>
      <button onClick={fitToScreen} title="Fit to screen" style={btnStyle}>
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
          <polyline points="15 3 21 3 21 9"/><polyline points="9 21 3 21 3 15"/>
          <line x1="21" y1="3" x2="14" y2="10"/><line x1="3" y1="21" x2="10" y2="14"/>
        </svg>
      </button>
      {state.status === 'ready' && (
        <span style={{ fontSize: 11, color: '#888', alignSelf: 'center', paddingLeft: 4 }}>
          {state.nodes.length} files · {state.data.edges.length} imports
        </span>
      )}
    </div>
  );

  const legend = (
    <div style={{
      position: 'absolute', bottom: 12, right: 12, zIndex: 10,
      background: 'rgba(20,20,20,0.85)', borderRadius: 8, padding: '8px 12px',
      backdropFilter: 'blur(8px)', border: '1px solid rgba(255,255,255,0.08)',
      display: 'flex', flexDirection: 'column', gap: 4,
    }}>
      {Object.entries(EXT_COLOR).map(([ext, color]) => (
        <div key={ext} style={{ display: 'flex', alignItems: 'center', gap: 6, fontSize: 11 }}>
          <span style={{ width: 10, height: 10, borderRadius: '50%', background: color, flexShrink: 0 }} />
          <span style={{ color: '#999' }}>{ext}</span>
        </div>
      ))}
    </div>
  );

  if (state.status === 'idle' || state.status === 'loading') {
    return (
      <div style={{ width: '100vw', height: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', flexDirection: 'column', gap: 16 }}>
        <Spinner />
        <span style={{ color: '#666', fontSize: 13 }}>Scanning workspace…</span>
      </div>
    );
  }

  if (state.status === 'error') {
    return (
      <div style={{ width: '100vw', height: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <div style={{ color: '#f87171', fontSize: 13 }}>Error: {state.message}</div>
      </div>
    );
  }

  const { nodes, data } = state;
  const nodeById = new Map(nodes.map(n => [n.id, n]));

  return (
    <div style={{ width: '100vw', height: '100vh', position: 'relative', overflow: 'hidden', userSelect: 'none' }}>
      {toolbar}
      {legend}

      {hovered && (
        <div style={{
          position: 'absolute', bottom: 12, left: 12, zIndex: 10,
          background: 'rgba(20,20,20,0.9)', borderRadius: 6, padding: '4px 10px',
          fontSize: 11, color: '#aaa', fontFamily: 'monospace',
          border: '1px solid rgba(255,255,255,0.08)', maxWidth: '60vw', wordBreak: 'break-all',
        }}>
          {hovered}
        </div>
      )}

      <svg
        ref={svgRef}
        width={dims.w}
        height={dims.h}
        style={{ display: 'block', cursor: isPanning.current ? 'grabbing' : 'grab' }}
        onWheel={onWheel}
        onPointerDown={onBgPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={onPointerUp}
        onPointerLeave={onPointerUp}
      >
        <defs>
          <marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto">
            <path d="M0,0 L0,6 L8,3 z" fill="rgba(255,255,255,0.2)" />
          </marker>
        </defs>

        <g transform={`translate(${transform.x},${transform.y}) scale(${transform.scale})`}>
          {/* Edges */}
          {data.edges.map((e, i) => {
            const s = nodeById.get(e.source);
            const t = nodeById.get(e.target);
            if (!s || !t) return null;
            const dx = t.x - s.x, dy = t.y - s.y;
            const len = Math.sqrt(dx * dx + dy * dy) || 1;
            const r = 14;
            const tx2 = t.x - (dx / len) * (r + 6);
            const ty2 = t.y - (dy / len) * (r + 6);
            const isHighlighted = hovered === s.id || hovered === t.id;
            return (
              <line
                key={i}
                x1={s.x} y1={s.y} x2={tx2} y2={ty2}
                stroke={isHighlighted ? 'rgba(255,255,255,0.5)' : 'rgba(255,255,255,0.12)'}
                strokeWidth={isHighlighted ? 1.5 : 1}
                markerEnd="url(#arrow)"
              />
            );
          })}

          {/* Nodes */}
          {nodes.map(n => {
            const color = nodeColor(n.ext);
            const isHovered = hovered === n.id;
            return (
              <g
                key={n.id}
                transform={`translate(${n.x},${n.y})`}
                style={{ cursor: 'pointer' }}
                onPointerDown={e => onNodePointerDown(e, n)}
                onClick={e => onNodeClick(e, n)}
                onPointerEnter={() => setHovered(n.id)}
                onPointerLeave={() => setHovered(null)}
              >
                <circle
                  r={isHovered ? 16 : 14}
                  fill={color}
                  fillOpacity={isHovered ? 1 : 0.8}
                  stroke={isHovered ? '#fff' : color}
                  strokeWidth={isHovered ? 1.5 : 0}
                  style={{ transition: 'r 0.1s, fill-opacity 0.1s' }}
                />
                <text
                  y={26}
                  textAnchor="middle"
                  fontSize={isHovered ? 11 : 10}
                  fill={isHovered ? '#fff' : '#bbb'}
                  style={{ pointerEvents: 'none', transition: 'font-size 0.1s' }}
                >
                  {n.label.length > 20 ? n.label.slice(0, 18) + '…' : n.label}
                </text>
              </g>
            );
          })}
        </g>
      </svg>
    </div>
  );
}

// ─── Micro components ─────────────────────────────────────────────────────────

const btnStyle: React.CSSProperties = {
  background: 'none', border: 'none', color: '#bbb', cursor: 'pointer',
  padding: '4px 6px', borderRadius: 4, display: 'flex', alignItems: 'center',
  transition: 'background 0.15s, color 0.15s',
};

function Spinner() {
  return (
    <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="#4FC3F7" strokeWidth="2" strokeLinecap="round">
      <style>{`@keyframes spin{to{transform:rotate(360deg)}} .sp{transform-origin:center;animation:spin 0.8s linear infinite}`}</style>
      <g className="sp">
        <circle cx="12" cy="12" r="10" strokeOpacity="0.15" />
        <path d="M12 2a10 10 0 0 1 10 10" />
      </g>
    </svg>
  );
}

