const esbuild = require('esbuild');

const isProd = process.argv.includes('--production');
const isWatch = process.argv.includes('--watch');

const extensionConfig = {
  entryPoints: ['src/extension.ts'],
  bundle: true,
  outfile: 'out/extension.js',
  external: ['vscode'],
  format: 'cjs',
  platform: 'node',
  target: 'node18',
  sourcemap: !isProd,
  minify: isProd,
};

const webviewBase = {
  bundle: true,
  format: 'iife',
  platform: 'browser',
  jsx: 'automatic',
  sourcemap: !isProd,
  minify: isProd,
  define: { 'process.env.NODE_ENV': isProd ? '"production"' : '"development"' },
};

const webviewConfig = { ...webviewBase, entryPoints: ['webview-ui/index.tsx'], outfile: 'out/webview.js' };
const codemapsConfig = { ...webviewBase, entryPoints: ['webview-ui/codemaps.tsx'], outfile: 'out/codemaps.js' };

async function main() {
  if (isWatch) {
    const [extCtx, webCtx] = await Promise.all([
      esbuild.context(extensionConfig),
      esbuild.context(webviewConfig),
    ]);
    await Promise.all([extCtx.watch(), webCtx.watch()]);
    console.log('Watching for changes...');
  } else {
    await Promise.all([
      esbuild.build(extensionConfig),
      esbuild.build(webviewConfig),
    ]);
    console.log('Build complete.');
  }
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

