import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';

// ─── Types ─────────────────────────────────────────────────────────────────────

interface CodemapNode { id: string; label: string; ext: string; dir: string }
interface CodemapEdge { source: string; target: string }
interface CodemapData  { nodes: CodemapNode[]; edges: CodemapEdge[]; root: string }
interface SimNode extends CodemapNode { x: number; y: number; vx: number; vy: number; pinned?: boolean }
interface FolderGroup  { cx: number; cy: number; r: number; hue: number; count: number }

// ─── VS Code API ───────────────────────────────────────────────────────────────

declare function acquireVsCodeApi(): { postMessage(msg: unknown): void };
const vscode = acquireVsCodeApi();

// ─── Constants ─────────────────────────────────────────────────────────────────

const EXT_COLOR: Record<string, string> = {
  '.ts': '#4FC3F7', '.tsx': '#CE93D8',
  '.js': '#FFD54F', '.jsx': '#FFAB40', '.mjs': '#80CBC4',
};
const BASE_R  = 10;
const MARGIN  = 100;

function nodeColor(ext: string) { return EXT_COLOR[ext] ?? '#90A4AE'; }

function dirHue(dir: string): number {
  let h = 5381;
  for (let i = 0; i < dir.length; i++) h = ((h << 5) + h + dir.charCodeAt(i)) & 0x7fffffff;
  return h % 360;
}

function nodeRadius(deg: number, maxDeg: number): number {
  return maxDeg > 0 ? BASE_R + (deg / maxDeg) * 8 : BASE_R;
}

// ─── Simulation ────────────────────────────────────────────────────────────────

function initSimNodes(raw: CodemapNode[], W: number, H: number): SimNode[] {
  // Sunflower spiral — better spread than a single circle
  const goldenAngle = Math.PI * (3 - Math.sqrt(5));
  const scale = Math.min(W, H) * 0.42;
  return raw.map((n, i) => {
    const r = Math.sqrt((i + 0.5) / raw.length) * scale;
    const theta = i * goldenAngle;
    return { ...n, x: W / 2 + r * Math.cos(theta), y: H / 2 + r * Math.sin(theta), vx: 0, vy: 0 };
  });
}

function totalTicksFor(n: number): number {
  if (n <= 50)  return 280;
  if (n <= 150) return 180;
  if (n <= 300) return 120;
  return 80;
}

function runTicks(
  nodes: SimNode[],
  nodeById: Map<string, SimNode>,
  edgeAdj: Map<string, string[]>,
  W: number, H: number, k: number,
  startTick: number, totalTicks: number, count: number,
) {
  for (let t = 0; t < count; t++) {
    const tick = startTick + t;
    const temp = k * Math.max(0.01, 1 - tick / totalTicks);

    // Reset velocities
    for (const n of nodes) { n.vx = 0; n.vy = 0; }

    // Repulsion O(n²/2) — symmetric, so we apply both directions at once
    for (let i = 0; i < nodes.length; i++) {
      for (let j = i + 1; j < nodes.length; j++) {
        const dx = nodes[i].x - nodes[j].x;
        const dy = nodes[i].y - nodes[j].y;
        const dist = Math.sqrt(dx * dx + dy * dy) || 0.01;
        const f    = (k * k) / dist;
        const fx   = (dx / dist) * f, fy = (dy / dist) * f;
        nodes[i].vx += fx; nodes[i].vy += fy;
        nodes[j].vx -= fx; nodes[j].vy -= fy;
      }
    }

    // Spring attraction along edges
    for (const [src, targets] of edgeAdj) {
      const s = nodeById.get(src);
      if (!s) continue;
      for (const tid of targets) {
        const tt = nodeById.get(tid);
        if (!tt) continue;
        const dx = tt.x - s.x, dy = tt.y - s.y;
        const dist = Math.sqrt(dx * dx + dy * dy) || 0.01;
        const f    = (dist * dist) / k;
        const fx   = (dx / dist) * f, fy = (dy / dist) * f;
        s.vx  += fx; s.vy  += fy;
        tt.vx -= fx; tt.vy -= fy;
      }
    }

    // Centering
    const cx = W / 2, cy = H / 2;
    for (const n of nodes) {
      n.vx += (cx - n.x) * 0.006;
      n.vy += (cy - n.y) * 0.006;
    }

    // Directory clustering — pull same-folder nodes together
    const cl: Record<string, { x: number; y: number; c: number }> = {};
    for (const n of nodes) {
      if (!cl[n.dir]) cl[n.dir] = { x: 0, y: 0, c: 0 };
      cl[n.dir].x += n.x; cl[n.dir].y += n.y; cl[n.dir].c++;
    }
    for (const c of Object.values(cl)) { c.x /= c.c; c.y /= c.c; }
    for (const n of nodes) {
      const c = cl[n.dir];
      if (c) { n.vx += (c.x - n.x) * 0.03; n.vy += (c.y - n.y) * 0.03; }
    }

    // Soft boundary — springy repulsion from edges instead of hard clamp
    for (const n of nodes) {
      if (n.x < MARGIN)         n.vx += (MARGIN - n.x) * 0.4;
      else if (n.x > W - MARGIN) n.vx -= (n.x - (W - MARGIN)) * 0.4;
      if (n.y < MARGIN)         n.vy += (MARGIN - n.y) * 0.4;
      else if (n.y > H - MARGIN) n.vy -= (n.y - (H - MARGIN)) * 0.4;
    }

    // Apply velocity with cooling
    for (const n of nodes) {
      if (n.pinned) continue;
      const speed   = Math.sqrt(n.vx * n.vx + n.vy * n.vy) || 1;
      const clamped = Math.min(speed, temp) / speed;
      n.x += n.vx * clamped;
      n.y += n.vy * clamped;
    }
  }
}

// ─── Component ─────────────────────────────────────────────────────────────────

export function CodemapsView() {
  const [dims, setDims]             = useState({ w: window.innerWidth, h: window.innerHeight });
  const [data, setData]             = useState<CodemapData | null>(null);
  const [phase, setPhase]           = useState<'idle' | 'loading' | 'simulating' | 'ready'>('idle');
  const [simProgress, setSimProgress] = useState(0);
  const [nodes, setNodes]           = useState<SimNode[]>([]);
  const [transform, setTransform]   = useState({ x: 0, y: 0, scale: 1 });
  const [hovered, setHovered]       = useState<string | null>(null);
  const [search, setSearch]         = useState('');
  const [showFolders, setShowFolders] = useState(true);

  // Mutable sim state kept in refs to avoid stale closures in the rAF loop
  const simRef      = useRef<SimNode[]>([]);
  const tickRef     = useRef(0);
  const totalRef    = useRef(0);
  const rafRef      = useRef<number>(0);

  const panStart    = useRef<{ px: number; py: number; tx: number; ty: number } | null>(null);
  const dragRef     = useRef<{ id: string; ox: number; oy: number } | null>(null);

  // ── Resize ──────────────────────────────────────────────────────────────────

  useEffect(() => {
    const onResize = () => setDims({ w: window.innerWidth, h: window.innerHeight });
    window.addEventListener('resize', onResize);
    return () => window.removeEventListener('resize', onResize);
  }, []);

  // ── Extension messages ───────────────────────────────────────────────────────

  useEffect(() => {
    const onMsg = (ev: MessageEvent) => {
      const msg = ev.data as { type: string; payload?: CodemapData };
      if (msg.type === 'loading') {
        cancelAnimationFrame(rafRef.current);
        setPhase('loading');
        setData(null);
        setNodes([]);
      } else if (msg.type === 'data' && msg.payload) {
        setData(msg.payload);
      }
    };
    window.addEventListener('message', onMsg);
    vscode.postMessage({ type: 'ready' });
    return () => window.removeEventListener('message', onMsg);
  }, []);

  // ── Start simulation when data arrives ──────────────────────────────────────

  useEffect(() => {
    if (!data) return;
    cancelAnimationFrame(rafRef.current);

    const { w: W, h: H } = dims;
    const k       = Math.sqrt((W * H) / Math.max(data.nodes.length, 1));
    const total   = totalTicksFor(data.nodes.length);
    const perFrame = Math.max(3, Math.ceil(total / 50)); // finish in ~50 frames

    simRef.current  = initSimNodes(data.nodes, W, H);
    tickRef.current = 0;
    totalRef.current = total;

    const nodeById = new Map(simRef.current.map(n => [n.id, n]));
    const edgeAdj  = new Map<string, string[]>();
    for (const e of data.edges) {
      if (!edgeAdj.has(e.source)) edgeAdj.set(e.source, []);
      edgeAdj.get(e.source)!.push(e.target);
    }

    setPhase('simulating');
    setSimProgress(0);

    let frame = 0;
    function step() {
      const elapsed = tickRef.current;
      if (elapsed >= total) {
        setNodes([...simRef.current]);
        setPhase('ready');
        return;
      }
      const count = Math.min(perFrame, total - elapsed);
      runTicks(simRef.current, nodeById, edgeAdj, W, H, k, elapsed, total, count);
      tickRef.current += count;
      frame++;

      // Push to React every ~5 frames so the user sees the graph settling
      if (frame % 5 === 0) {
        setSimProgress(tickRef.current / total);
        setNodes([...simRef.current]);
      }
      rafRef.current = requestAnimationFrame(step);
    }
    rafRef.current = requestAnimationFrame(step);
    return () => cancelAnimationFrame(rafRef.current);
  }, [data]); // intentionally omitting dims — sim runs once per data load

  // ── Derived data ─────────────────────────────────────────────────────────────

  const { degree, maxDeg, folderGroups, nodeById } = useMemo(() => {
    const deg = new Map<string, number>();
    if (data) {
      for (const e of data.edges) {
        deg.set(e.source, (deg.get(e.source) ?? 0) + 1);
        deg.set(e.target, (deg.get(e.target) ?? 0) + 1);
      }
    }
    let mxDeg = 0;
    for (const d of deg.values()) if (d > mxDeg) mxDeg = d;

    const nbid = new Map(nodes.map(n => [n.id, n]));

    const fg: Record<string, FolderGroup> = {};
    for (const n of nodes) {
      if (!fg[n.dir]) fg[n.dir] = { cx: 0, cy: 0, r: 0, hue: dirHue(n.dir), count: 0 };
      fg[n.dir].cx += n.x; fg[n.dir].cy += n.y; fg[n.dir].count++;
    }
    for (const g of Object.values(fg)) { g.cx /= g.count; g.cy /= g.count; }
    for (const n of nodes) {
      const g = fg[n.dir];
      if (!g) continue;
      const dist = Math.sqrt((n.x - g.cx) ** 2 + (n.y - g.cy) ** 2);
      g.r = Math.max(g.r, dist + 36);
    }

    return { degree: deg, maxDeg: mxDeg, folderGroups: fg, nodeById: nbid };
  }, [nodes, data]);

  // Search match set (null = no filter active)
  const matchSet = useMemo<Set<string> | null>(() => {
    const q = search.trim().toLowerCase();
    if (!q) return null;
    return new Set(nodes.filter(n => n.id.toLowerCase().includes(q)).map(n => n.id));
  }, [search, nodes]);

  // ── Fit to screen ────────────────────────────────────────────────────────────

  const fitToScreen = useCallback(() => {
    if (nodes.length === 0) return;
    const xs = nodes.map(n => n.x), ys = nodes.map(n => n.y);
    const minX = Math.min(...xs) - 80, maxX = Math.max(...xs) + 80;
    const minY = Math.min(...ys) - 80, maxY = Math.max(...ys) + 80;
    const scale = Math.min(dims.w / (maxX - minX), dims.h / (maxY - minY), 3);
    setTransform({
      scale,
      x: dims.w / 2 - ((minX + maxX) / 2) * scale,
      y: dims.h / 2 - ((minY + maxY) / 2) * scale,
    });
  }, [nodes, dims]);

  // ── Zoom ─────────────────────────────────────────────────────────────────────

  const onWheel = (e: React.WheelEvent) => {
    e.preventDefault();
    const factor = e.deltaY < 0 ? 1.12 : 1 / 1.12;
    setTransform(prev => {
      const ns = Math.max(0.04, Math.min(12, prev.scale * factor));
      return {
        scale: ns,
        x: e.clientX - (e.clientX - prev.x) * (ns / prev.scale),
        y: e.clientY - (e.clientY - prev.y) * (ns / prev.scale),
      };
    });
  };

  // ── Pan + drag ───────────────────────────────────────────────────────────────

  const screenToSvg = (px: number, py: number) => ({
    x: (px - transform.x) / transform.scale,
    y: (py - transform.y) / transform.scale,
  });

  const onBgDown = (e: React.PointerEvent) => {
    if (e.button !== 0 || dragRef.current) return;
    panStart.current = { px: e.clientX, py: e.clientY, tx: transform.x, ty: transform.y };
    (e.target as Element).setPointerCapture(e.pointerId);
  };

  const onPointerMove = (e: React.PointerEvent) => {
    if (dragRef.current) {
      const { x, y } = screenToSvg(e.clientX, e.clientY);
      const { id, ox, oy } = dragRef.current;
      const nx = x - ox, ny = y - oy;
      // Mutate simRef so the live simulation respects the pin
      const sn = simRef.current.find(n => n.id === id);
      if (sn) { sn.x = nx; sn.y = ny; sn.pinned = true; }
      setNodes(prev => prev.map(pn => pn.id === id ? { ...pn, x: nx, y: ny, pinned: true } : pn));
    } else if (panStart.current) {
      const { tx, ty, px, py } = panStart.current;
      setTransform(prev => ({ ...prev, x: tx + e.clientX - px, y: ty + e.clientY - py }));
    }
  };

  const onPointerUp = () => { panStart.current = null; dragRef.current = null; };

  const onNodeDown = (e: React.PointerEvent, n: SimNode) => {
    e.stopPropagation();
    const { x, y } = screenToSvg(e.clientX, e.clientY);
    dragRef.current = { id: n.id, ox: x - n.x, oy: y - n.y };
    (e.target as Element).setPointerCapture(e.pointerId);
  };

  const onNodeClick = (e: React.MouseEvent, n: SimNode) => {
    e.stopPropagation();
    vscode.postMessage({ type: 'openFile', path: n.id });
  };

  // ── Render ───────────────────────────────────────────────────────────────────

  const sc = transform.scale;
  const labelSize = Math.round(10 / Math.sqrt(sc)); // constant visual size

  if (phase === 'idle' || phase === 'loading') {
    return (
      <FullCenter>
        <Spinner />
        <span style={{ color: '#666', fontSize: 13, marginTop: 12 }}>Scanning workspace…</span>
      </FullCenter>
    );
  }

  return (
    <div style={{ width: '100vw', height: '100vh', position: 'relative', overflow: 'hidden', userSelect: 'none' }}>

      {/* ── Toolbar ── */}
      <div style={TOOLBAR}>
        <IconBtn onClick={() => { vscode.postMessage({ type: 'refresh' }); }} title="Refresh">
          <RefreshIcon />
        </IconBtn>
        <IconBtn onClick={fitToScreen} title="Fit to screen" disabled={nodes.length === 0}>
          <FitIcon />
        </IconBtn>
        <Sep />
        <IconBtn
          onClick={() => setShowFolders(v => !v)}
          title={showFolders ? 'Hide folder groups' : 'Show folder groups'}
          active={showFolders}
        >
          <FolderIcon />
        </IconBtn>
        <Sep />
        <input
          value={search}
          onChange={e => setSearch(e.target.value)}
          placeholder="Filter files…"
          style={SEARCH_INPUT}
          spellCheck={false}
        />
        {data && (
          <span style={{ fontSize: 11, color: '#555', whiteSpace: 'nowrap' }}>
            {nodes.length} files · {data.edges.length} imports
            {matchSet ? ` · ${matchSet.size} match` : ''}
          </span>
        )}
      </div>

      {/* ── Legend ── */}
      <div style={LEGEND}>
        {Object.entries(EXT_COLOR).map(([ext, color]) => (
          <div key={ext} style={{ display: 'flex', alignItems: 'center', gap: 5, fontSize: 11 }}>
            <span style={{ width: 8, height: 8, borderRadius: '50%', background: color, flexShrink: 0 }} />
            <span style={{ color: '#666' }}>{ext}</span>
          </div>
        ))}
      </div>

      {/* ── Status bar ── */}
      <div style={{ position: 'absolute', bottom: 12, left: 12, zIndex: 10 }}>
        {phase === 'simulating' ? (
          <div style={{ ...PILL, display: 'flex', alignItems: 'center', gap: 8 }}>
            <Spinner size={12} />
            <span style={{ fontSize: 11, color: '#777' }}>
              Laying out… {Math.round(simProgress * 100)}%
            </span>
            <div style={{ width: 80, height: 3, borderRadius: 2, background: 'rgba(255,255,255,0.08)' }}>
              <div style={{ width: `${simProgress * 100}%`, height: '100%', borderRadius: 2, background: '#4FC3F7', transition: 'width 0.1s' }} />
            </div>
          </div>
        ) : hovered ? (
          <div style={{ ...PILL, fontFamily: 'monospace', fontSize: 11, color: '#999', maxWidth: '70vw', wordBreak: 'break-all' }}>
            {hovered}
            {degree.get(hovered) !== undefined && (
              <span style={{ color: '#555', marginLeft: 8 }}>
                {degree.get(hovered)} connection{(degree.get(hovered) ?? 0) !== 1 ? 's' : ''}
              </span>
            )}
          </div>
        ) : null}
      </div>

      {/* ── SVG Graph ── */}
      <svg
        width={dims.w} height={dims.h}
        style={{ display: 'block', cursor: 'grab' }}
        onWheel={onWheel}
        onPointerDown={onBgDown}
        onPointerMove={onPointerMove}
        onPointerUp={onPointerUp}
        onPointerLeave={onPointerUp}
        onPointerCancel={onPointerUp}
      >
        <defs>
          <marker id="arrow" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto">
            <path d="M0,0 L0,6 L6,3 z" fill="rgba(255,255,255,0.2)" />
          </marker>
        </defs>

        <g transform={`translate(${transform.x},${transform.y}) scale(${sc})`}>

          {/* Folder group circles */}
          {showFolders && Object.entries(folderGroups).map(([dir, g]) =>
            g.count > 1 ? (
              <g key={dir}>
                <circle
                  cx={g.cx} cy={g.cy} r={g.r}
                  fill={`hsla(${g.hue},40%,18%,0.22)`}
                  stroke={`hsla(${g.hue},55%,55%,0.28)`}
                  strokeWidth={1 / sc}
                />
                {sc > 0.35 && (
                  <text
                    x={g.cx} y={g.cy - g.r + 14 / sc}
                    textAnchor="middle"
                    fontSize={11 / sc}
                    fill={`hsla(${g.hue},60%,65%,0.65)`}
                    style={{ pointerEvents: 'none' }}
                  >
                    {dir === '.' ? '(root)' : dir.split('/').pop()}
                  </text>
                )}
              </g>
            ) : null
          )}

          {/* Edges */}
          {data && data.edges.map((e, i) => {
            const s = nodeById.get(e.source), t = nodeById.get(e.target);
            if (!s || !t) return null;
            const dx = t.x - s.x, dy = t.y - s.y;
            const len = Math.sqrt(dx * dx + dy * dy) || 1;
            const sr  = nodeRadius(degree.get(s.id) ?? 0, maxDeg);
            const tr  = nodeRadius(degree.get(t.id) ?? 0, maxDeg) + 5;
            const x1  = s.x + (dx / len) * sr, y1 = s.y + (dy / len) * sr;
            const x2  = t.x - (dx / len) * tr, y2 = t.y - (dy / len) * tr;
            const lit  = hovered === s.id || hovered === t.id;
            const dim  = matchSet !== null && !matchSet.has(s.id) && !matchSet.has(t.id);
            return (
              <line
                key={i}
                x1={x1} y1={y1} x2={x2} y2={y2}
                stroke={lit ? 'rgba(255,255,255,0.6)' : 'rgba(255,255,255,0.1)'}
                strokeWidth={(lit ? 1.5 : 0.8) / sc}
                strokeOpacity={dim ? 0.08 : 1}
                markerEnd="url(#arrow)"
              />
            );
          })}

          {/* Nodes */}
          {nodes.map(n => {
            const deg = degree.get(n.id) ?? 0;
            const r   = nodeRadius(deg, maxDeg);
            const col = nodeColor(n.ext);
            const hov = hovered === n.id;
            const dim = matchSet !== null && !matchSet.has(n.id);
            // Show label: always when hovered; at mid-zoom for hubs; at high zoom for all
            const showLabel = hov || sc > 0.6 || (sc > 0.28 && deg >= maxDeg * 0.25);
            return (
              <g
                key={n.id}
                transform={`translate(${n.x},${n.y})`}
                style={{ cursor: 'pointer', opacity: dim ? 0.18 : 1 }}
                onPointerDown={ev => onNodeDown(ev, n)}
                onClick={ev => onNodeClick(ev, n)}
                onPointerEnter={() => setHovered(n.id)}
                onPointerLeave={() => setHovered(null)}
              >
                <circle
                  r={hov ? r + 4 : r}
                  fill={col}
                  fillOpacity={hov ? 1 : 0.82}
                  stroke={hov ? '#fff' : col}
                  strokeWidth={hov ? 1.5 / sc : 0}
                />
                {showLabel && (
                  <text
                    y={r + labelSize * 1.1}
                    textAnchor="middle"
                    fontSize={hov ? Math.max(10, labelSize) : labelSize}
                    fill={hov ? '#fff' : '#aaa'}
                    style={{ pointerEvents: 'none' }}
                  >
                    {n.label.length > 24 ? n.label.slice(0, 22) + '…' : n.label}
                  </text>
                )}
              </g>
            );
          })}

        </g>
      </svg>
    </div>
  );
}

// ─── Sub-components ─────────────────────────────────────────────────────────────

function FullCenter({ children }: { children: React.ReactNode }) {
  return (
    <div style={{ width: '100vw', height: '100vh', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center' }}>
      {children}
    </div>
  );
}

function Spinner({ size = 28 }: { size?: number }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="#4FC3F7" strokeWidth="2" strokeLinecap="round">
      <style>{`@keyframes cm-spin{to{transform:rotate(360deg)}} .cm-sp{transform-origin:12px 12px;animation:cm-spin 0.8s linear infinite}`}</style>
      <g className="cm-sp">
        <circle cx="12" cy="12" r="10" strokeOpacity="0.12" />
        <path d="M12 2a10 10 0 0 1 10 10" />
      </g>
    </svg>
  );
}

function IconBtn({ onClick, title, children, disabled, active }: {
  onClick: () => void; title: string; children: React.ReactNode;
  disabled?: boolean; active?: boolean;
}) {
  return (
    <button
      onClick={onClick}
      title={title}
      disabled={disabled}
      style={{
        background: active ? 'rgba(79,195,247,0.15)' : 'none',
        border: 'none',
        color: active ? '#4FC3F7' : disabled ? '#444' : '#aaa',
        cursor: disabled ? 'default' : 'pointer',
        padding: '4px 7px',
        borderRadius: 5,
        display: 'flex', alignItems: 'center',
      }}
    >
      {children}
    </button>
  );
}

function Sep() {
  return <div style={{ width: 1, height: 16, background: 'rgba(255,255,255,0.07)', margin: '0 2px' }} />;
}

function RefreshIcon() {
  return <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><polyline points="23 4 23 10 17 10"/><polyline points="1 20 1 14 7 14"/><path d="M3.51 9a9 9 0 0 1 14.85-3.36L23 10M1 14l4.64 4.36A9 9 0 0 0 20.49 15"/></svg>;
}

function FitIcon() {
  return <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><polyline points="15 3 21 3 21 9"/><polyline points="9 21 3 21 3 15"/><line x1="21" y1="3" x2="14" y2="10"/><line x1="3" y1="21" x2="10" y2="14"/></svg>;
}

function FolderIcon() {
  return <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><path d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z"/></svg>;
}

// ─── Style constants ────────────────────────────────────────────────────────────

const GLASS: React.CSSProperties = {
  background: 'rgba(14,14,14,0.88)',
  border: '1px solid rgba(255,255,255,0.07)',
  backdropFilter: 'blur(10px)',
  borderRadius: 8,
};

const TOOLBAR: React.CSSProperties = {
  ...GLASS,
  position: 'absolute', top: 12, left: 12, zIndex: 10,
  display: 'flex', alignItems: 'center', gap: 4, padding: '5px 10px',
};

const LEGEND: React.CSSProperties = {
  ...GLASS,
  position: 'absolute', bottom: 12, right: 12, zIndex: 10,
  padding: '8px 12px', display: 'flex', flexDirection: 'column', gap: 5,
};

const PILL: React.CSSProperties = {
  ...GLASS, padding: '4px 10px',
};

const SEARCH_INPUT: React.CSSProperties = {
  background: 'rgba(255,255,255,0.05)',
  border: '1px solid rgba(255,255,255,0.08)',
  borderRadius: 5, color: '#ccc', fontSize: 12,
  padding: '3px 8px', outline: 'none', width: 140,
};

