import * as vscode from 'vscode';
import * as path from 'path';
import * as fs from 'fs';

export interface CodemapNode {
  id: string;    // workspace-relative path, e.g. "src/extension.ts"
  label: string; // filename, e.g. "extension.ts"
  ext: string;   // e.g. ".ts"
  dir: string;   // parent folder, e.g. "src"
}

export interface CodemapEdge {
  source: string; // node id
  target: string; // node id
}

export interface CodemapData {
  nodes: CodemapNode[];
  edges: CodemapEdge[];
  root: string;
}

const IMPORT_RE = /(?:^|\s)import\s+(?:[\s\S]*?\s+from\s+)?['"]([^'"]+)['"]/gm;
const REQUIRE_RE = /require\s*\(\s*['"]([^'"]+)['"]\s*\)/g;
const DYNAMIC_IMPORT_RE = /import\s*\(\s*['"]([^'"]+)['"]\s*\)/g;
const SOURCE_EXTS = ['.ts', '.tsx', '.js', '.jsx', '.mjs'];

function resolveImport(fromAbs: string, importPath: string, root: string): string | null {
  if (!importPath.startsWith('.')) return null;

  const dir = path.dirname(fromAbs);
  const base = path.resolve(dir, importPath);

  // exact match
  if (fs.existsSync(base) && fs.statSync(base).isFile()) {
    return path.relative(root, base).replace(/\\/g, '/');
  }

  // with extension
  for (const ext of SOURCE_EXTS) {
    const candidate = base + ext;
    if (fs.existsSync(candidate)) {
      return path.relative(root, candidate).replace(/\\/g, '/');
    }
  }

  // as directory index
  for (const ext of SOURCE_EXTS) {
    const candidate = path.join(base, `index${ext}`);
    if (fs.existsSync(candidate)) {
      return path.relative(root, candidate).replace(/\\/g, '/');
    }
  }

  return null;
}

export async function buildCodemapData(): Promise<CodemapData> {
  const folders = vscode.workspace.workspaceFolders;
  const root = folders?.[0]?.uri.fsPath ?? '';

  const files = await vscode.workspace.findFiles(
    '**/*.{ts,tsx,js,jsx,mjs}',
    '{node_modules,out,dist,build,.git}/**'
  );

  const nodeMap = new Map<string, CodemapNode>();
  const edges: CodemapEdge[] = [];
  const edgeSet = new Set<string>();

  for (const file of files) {
    const rel = path.relative(root, file.fsPath).replace(/\\/g, '/');
    nodeMap.set(rel, {
      id: rel,
      label: path.basename(rel),
      ext: path.extname(rel),
      dir: path.dirname(rel),
    });
  }

  for (const file of files) {
    const rel = path.relative(root, file.fsPath).replace(/\\/g, '/');
    let content: string;
    try {
      content = fs.readFileSync(file.fsPath, 'utf8');
    } catch {
      continue;
    }

    const patterns = [IMPORT_RE, REQUIRE_RE, DYNAMIC_IMPORT_RE];
    for (const re of patterns) {
      re.lastIndex = 0;
      let m: RegExpExecArray | null;
      while ((m = re.exec(content)) !== null) {
        const target = resolveImport(file.fsPath, m[1], root);
        if (target && nodeMap.has(target) && target !== rel) {
          const key = `${rel}→${target}`;
          if (!edgeSet.has(key)) {
            edgeSet.add(key);
            edges.push({ source: rel, target });
          }
        }
      }
    }
  }

  return { nodes: Array.from(nodeMap.values()), edges, root };
}
